import java.util.TreeSet;

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        return cols <= rows ? compressColumns(matrix, k) : compressRows(matrix, k);
    }

    private int compressColumns(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int best = Integer.MIN_VALUE;
        for (int left = 0; left < cols; left++) {
            int[] rowSums = new int[rows];
            for (int right = left; right < cols; right++) {
                for (int row = 0; row < rows; row++) {
                    rowSums[row] += matrix[row][right];
                }
                best = Math.max(best, bestSubarrayNoMoreThanK(rowSums, k));
                if (best == k) {
                    return k;
                }
            }
        }
        return best;
    }

    private int compressRows(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int best = Integer.MIN_VALUE;
        for (int top = 0; top < rows; top++) {
            int[] columnSums = new int[cols];
            for (int bottom = top; bottom < rows; bottom++) {
                for (int col = 0; col < cols; col++) {
                    columnSums[col] += matrix[bottom][col];
                }
                best = Math.max(best, bestSubarrayNoMoreThanK(columnSums, k));
                if (best == k) {
                    return k;
                }
            }
        }
        return best;
    }

    private int bestSubarrayNoMoreThanK(int[] nums, int k) {
        TreeSet<Integer> prefixes = new TreeSet<>();
        prefixes.add(0);
        int prefix = 0;
        int best = Integer.MIN_VALUE;
        for (int value : nums) {
            prefix += value;
            Integer ceiling = prefixes.ceiling(prefix - k);
            if (ceiling != null) {
                best = Math.max(best, prefix - ceiling);
            }
            prefixes.add(prefix);
        }
        return best;
    }
}

