import java.util.ArrayList;
import java.util.List;

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int best = Integer.MIN_VALUE;
        for (int top = 0; top < rows; top++) {
            int[] columnSums = new int[cols];
            for (int bottom = top; bottom < rows; bottom++) {
                for (int col = 0; col < cols; col++) {
                    columnSums[col] += matrix[bottom][col];
                }
                best = Math.max(best, bestSubarrayNoMoreThanK(columnSums, k));
                if (best == k) {
                    return k;
                }
            }
        }
        return best;
    }

    private int bestSubarrayNoMoreThanK(int[] nums, int k) {
        List<Integer> prefixes = new ArrayList<>();
        prefixes.add(0);
        int prefix = 0;
        int best = Integer.MIN_VALUE;
        for (int value : nums) {
            prefix += value;
            int targetIndex = lowerBound(prefixes, prefix - k);
            if (targetIndex < prefixes.size()) {
                best = Math.max(best, prefix - prefixes.get(targetIndex));
            }
            prefixes.add(lowerBound(prefixes, prefix), prefix);
        }
        return best;
    }

    private int lowerBound(List<Integer> values, int target) {
        int lo = 0;
        int hi = values.size();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (values.get(mid) < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] prefix = new int[rows + 1][cols + 1];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                prefix[row + 1][col + 1] = matrix[row][col]
                        + prefix[row][col + 1]
                        + prefix[row + 1][col]
                        - prefix[row][col];
            }
        }

        int best = Integer.MIN_VALUE;
        for (int top = 0; top < rows; top++) {
            for (int left = 0; left < cols; left++) {
                for (int bottom = top; bottom < rows; bottom++) {
                    for (int right = left; right < cols; right++) {
                        int sum = prefix[bottom + 1][right + 1]
                                - prefix[top][right + 1]
                                - prefix[bottom + 1][left]
                                + prefix[top][left];
                        if (sum <= k) {
                            best = Math.max(best, sum);
                        }
                    }
                }
            }
        }
        return best;
    }
}
